import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        return self._request_with_retries(url, method='GET')

    def _request_with_retries(self, url: str, method: str = 'GET') -> str:
        # Handle 5xx errors: retry once after 1s
        for attempt in range(2):  # 0 and 1
            try:
                req = urllib.request.Request(url, method=method)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                status_code = response.getcode()

                if status_code == 429:
                    # Rate limit: retry up to 3 times with exponential backoff
                    return self._handle_rate_limit(url, method)
                elif 500 <= status_code < 600:
                    # 5xx: if not first attempt, raise ServerError
                    if attempt == 0:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error: {status_code}")
                elif 400 <= status_code < 500:
                    # 4xx except 429: raise ClientError immediately
                    raise ClientError(f"Client error: {status_code}")
                else:
                    return body
            except urllib.error.HTTPError as e:
                status_code = e.code
                if status_code == 429:
                    return self._handle_rate_limit(url, method)
                elif 500 <= status_code < 600:
                    if attempt == 0:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error: {status_code}") from e
                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error: {status_code}") from e
                else:
                    raise
            except urllib.error.URLError as e:
                # Network error: retry once after 1s
                if attempt == 0:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError(f"Connection error: {e}") from e

        # If we get here, it means we exhausted retries for 5xx or network errors
        raise ServerError("Max retries exceeded for server error")

    def _handle_rate_limit(self, url: str, method: str = 'GET') -> str:
        # Retry up to 3 times with exponential backoff: 0.5s, 1s, 2s
        backoff_times = [0.5, 1.0, 2.0]
        for i, backoff in enumerate(backoff_times):
            time.sleep(backoff)
            try:
                req = urllib.request.Request(url, method=method)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                status_code = response.getcode()

                if status_code == 429:
                    continue
                elif 500 <= status_code < 600:
                    # If we get a 5xx during rate limit retries, handle it
                    # But per spec, we should raise RateLimitError if still failing after 3 retries
                    # Let's just continue and if we exit the loop, raise RateLimitError
                    continue
                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error: {status_code}")
                else:
                    return body
            except urllib.error.HTTPError as e:
                status_code = e.code
                if status_code == 429:
                    continue
                elif 500 <= status_code < 600:
                    continue
                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error: {status_code}") from e
                else:
                    raise
            except urllib.error.URLError as e:
                continue

        raise RateLimitError("Rate limit exceeded after 3 retries")
